import {pickerMarkup,bindCurriculumPicker,createCurriculumState,questionMatchesCurriculum,resetCurriculumSelection} from './curriculum-picker.js';
import {openPaperDestination} from './papers.js';

const levels=[['all','전체'],['low','하'],['midlow','중하'],['mid','중'],['high','상'],['top','최상']];
export function difficultyLevel(n){return n<=2?'low':n<=3?'midlow':n<=5?'mid':n<=7?'high':'top';}
export function filterStudioQuestions(questions,{grade,units=[],level='all',answer='',query='',curriculum}){
 const tokens=query.trim().toLowerCase().split(/\s+/).filter(Boolean);
 return questions.filter(q=>q.grade===grade&&questionMatchesCurriculum(q,curriculum)&&(!units.length||units.includes(q.tags?.[1]||q.tags?.[0]))&&(level==='all'||difficultyLevel(q.difficulty)===level)&&(!answer||q.answerType===answer)&&tokens.every(t=>[q.text,q.title,q.unit,...(q.tags||[])].join(' ').toLowerCase().includes(t)));
}
export function studioUnits(questions,grade){const groups=new Map();for(const q of questions.filter(q=>q.grade===grade)){const parent=q.tags?.[0]||'전체',child=q.tags?.[1]||parent;if(!groups.has(parent))groups.set(parent,new Map());const children=groups.get(parent);children.set(child,(children.get(child)||0)+1);}return [...groups].map(([label,children])=>({label,children:[...children].map(([label,count])=>({label,count}))}));}
let cleanupPicker=()=>{};
const state={curriculum:createCurriculumState(),grade:'중1',units:[],level:'all',answer:'',query:'',selected:new Set(),collapsed:new Set()};
export function setStudioSearch(query){state.query=query;state.units=[];resetCurriculumSelection(state.curriculum);state.level='all';state.answer='';state.grade='중1';}
export function renderBankStudio(container,ctx,parts=[]){
 cleanupPicker();
 const {ui,store,questions,grades,go,subscribe,requestQuestion}=ctx;
 const {esc,icon,questionCard,toast}=ui;
 const requested=parts[1]||state.grade;
 if(requested!==state.grade){state.grade=grades.includes(requested)?requested:'중1';state.units=[];resetCurriculumSelection(state.curriculum);state.query='';state.selected.clear();}
 for(const id of state.selected)if(!store.canUseQuestion(id,'bank'))state.selected.delete(id);
 const list=filterStudioQuestions(questions,state),groups=studioUnits(questions,state.grade),active=store.isActive('bank');
 const chosen=questions.filter(q=>state.selected.has(q.id));
 const rerender=()=>renderBankStudio(container,ctx,['bank',state.grade]);
 const captureQuery=()=>{const input=container.querySelector('[name=query]');if(input)state.query=input.value;};
 const add=id=>{if(!store.canUseQuestion(id,'bank'))return subscribe('bank');state.selected.has(id)?state.selected.delete(id):state.selected.add(id);rerender();};
 container.innerHTML=`<div class="split-view bank-studio"><aside class="context-sidebar studio-sidebar"><div class="side-heading">수학비서 DB</div><form id="side-search-form" class="studio-global-search">${icon('search')}<input id="side-search" aria-label="수학비서 DB 전체 검색" placeholder="수학비서 DB 전체 검색"><button aria-label="전체 검색">${icon('chevron')}</button></form><div class="studio-sections"><a href="#library/materials">${icon('db')} 자료 DB</a><a class="active" href="#bank/중1">${icon('bank')} 문제은행</a></div><div class="studio-side-label">학년 선택</div><div class="studio-grades">${grades.map(g=>`<a href="#bank/${g}" class="${g===state.grade?'active':''}">${g}</a>`).join('')}</div><div class="studio-unit-head"><strong>단원 · 유형</strong><button class="text-btn" data-unit-reset>전체 보기</button></div>${pickerMarkup('studio',state.curriculum)}<p class="studio-side-note">실제 수학비서 문항 표본<br>중1 9문항 · 고1 3문항</p></aside><section class="studio-main"><header class="studio-heading"><div><div class="breadcrumb"><a href="#library">수학비서 DB</a>${icon('chevron')}문제은행</div><h1>${esc(state.grade)} 문제은행</h1><p>수업할 단원을 고르고, 필요한 문항만 담으세요.</p></div><button class="btn ${active?'':'primary'}" data-studio-subscribe>${active?'문제은행 구독 중':'월 39,000원 · 구독하기'}</button></header><div class="studio-mode-tabs"><a href="#library/materials">자료 DB</a><span class="active">문제은행</span><span class="grow"></span><button class="text-btn" data-studio-help>이용 방법</button></div><div class="studio-columns"><div class="studio-results"><form id="studio-filter"><div class="studio-difficulties"><span>난이도</span>${levels.map(([id,label])=>`<button type="button" data-level="${id}" class="${id===state.level?'active':''}">${label}</button>`).join('')}</div><div class="studio-search-row"><select name="answer" aria-label="정답 종류"><option value="">정답 종류 전체</option>${['객관식','주관식','증명','O/X'].map(a=>`<option ${a===state.answer?'selected':''}>${a}</option>`).join('')}</select><div class="searchbox">${icon('search')}<input name="query" value="${esc(state.query)}" placeholder="텍스트·수식 검색" aria-label="텍스트 및 수식 검색"><button class="btn small">검색</button></div><button type="button" class="icon-btn" data-filter-reset aria-label="문항 필터 초기화">${icon('close')}</button></div></form>${state.units.length?`<div class="studio-applied">${state.units.map(u=>`<button data-remove-unit="${esc(u)}">${esc(u)} ${icon('close')}</button>`).join('')}</div>`:''}<div class="studio-result-toolbar"><label class="checkbox"><input type="checkbox" data-select-visible ${list.length&&list.every(q=>state.selected.has(q.id))?'checked':''}>검색 결과 전체 선택</label><strong>${list.length}문항</strong><span class="grow"></span><span>단원 순</span></div>${!active?`<div class="studio-lock-info">${icon('lock')}<span>${store.getState().subscriptions.bank.status==='expired'?'구독이 종료됐어요. 다시 구독하면 담은 문항을 이용할 수 있어요.':'구독하면 원하는 문항을 골라 내 문제지에 담을 수 있어요.'}</span><button class="text-btn" data-studio-subscribe>구독 안내</button></div>`:''}<div class="studio-question-list">${list.length?list.map(q=>questionCard(q,{store,source:'bank',selectable:true,selected:state.selected.has(q.id)})).join(''):`<div class="empty"><h3>${groups.length?'조건에 맞는 문항이 없습니다.':'이 학년의 문항 표본은 준비 중입니다.'}</h3><p>${groups.length?'단원이나 검색 조건을 바꿔 보세요.':'중1과 고1에서 실제 문항을 확인할 수 있어요.'}</p><button class="btn" data-filter-reset>조건 초기화</button><a class="btn" href="#bank/중1">중1 보기</a></div>`}</div></div><aside class="studio-basket"><div class="studio-basket-head"><h2>담은 문항 <em>${chosen.length}</em></h2><button class="text-btn" data-clear-basket ${chosen.length?'':'disabled'}>비우기</button></div>${chosen.length?`<div class="studio-stats"><span>객관식 <b>${chosen.filter(q=>q.answerType==='객관식').length}</b></span><span>주관식 <b>${chosen.filter(q=>q.answerType==='주관식').length}</b></span><span>평균 난이도 <b>${(chosen.reduce((n,q)=>n+q.difficulty,0)/chosen.length).toFixed(1)}</b></span></div><ol class="studio-picked">${chosen.map(q=>`<li><span class="studio-picked-number">${q.number}</span><div><strong>${esc(q.tags?.at(-1)||q.title)}</strong><small>${esc(q.grade)} · 난이도 ${q.difficulty}</small></div><button class="icon-btn" data-remove-question="${q.id}" aria-label="${q.number}번 담기 취소">${icon('close')}</button></li>`).join('')}</ol>`:`<div class="studio-basket-empty">${icon('paper')}<strong>어떤 문제를 담아 볼까요?</strong><p>왼쪽 문항의 체크박스를 누르면<br>이곳에 모아 볼 수 있어요.</p></div>`}<div class="studio-basket-footer"><button class="btn primary" data-basket-paper ${chosen.length?'':'disabled'}>${icon('plus')}내 문제지에 담기${chosen.length?` (${chosen.length})`:''}</button><p>기존 문제지를 선택하거나 새로 만들 수 있어요.</p></div></aside></div></section></div>`;
 cleanupPicker=bindCurriculumPicker(container,'studio',{questions,state:state.curriculum,onChange:()=>{captureQuery();rerender();}});
 container.querySelector('#side-search-form').onsubmit=e=>{e.preventDefault();ctx.searchLibrary?.(container.querySelector('#side-search').value);};
 container.querySelectorAll('[data-studio-subscribe]').forEach(b=>b.onclick=()=>subscribe('bank'));
 container.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>{captureQuery();state.level=b.dataset.level;rerender();});
 container.querySelectorAll('[data-unit]').forEach(c=>c.onchange=()=>{captureQuery();state.units=c.checked?[...state.units,c.dataset.unit]:state.units.filter(x=>x!==c.dataset.unit);rerender();});
 container.querySelectorAll('[data-remove-unit]').forEach(b=>b.onclick=()=>{captureQuery();state.units=state.units.filter(x=>x!==b.dataset.removeUnit);rerender();});
 container.querySelector('[data-unit-reset]').onclick=()=>{state.units=[];resetCurriculumSelection(state.curriculum);rerender();};
 container.querySelectorAll('[data-toggle-unit]').forEach(b=>b.onclick=()=>{const unit=b.dataset.toggleUnit;state.collapsed.has(unit)?state.collapsed.delete(unit):state.collapsed.add(unit);rerender();});
 container.querySelector('#studio-filter').onsubmit=e=>{e.preventDefault();state.answer=e.target.elements.answer.value;state.query=e.target.elements.query.value;rerender();};
 container.querySelector('[name=answer]').onchange=e=>{captureQuery();state.answer=e.target.value;rerender();};
 container.querySelectorAll('[data-filter-reset]').forEach(b=>b.onclick=()=>{state.units=[];resetCurriculumSelection(state.curriculum);state.query='';state.level='all';state.answer='';rerender();});
 container.querySelector('[data-select-visible]').onchange=e=>{if(!active){e.target.checked=false;return subscribe('bank');}list.forEach(q=>e.target.checked&&store.canUseQuestion(q.id,'bank')?state.selected.add(q.id):state.selected.delete(q.id));rerender();};
 container.querySelectorAll('[data-qcheck]').forEach(b=>b.onchange=()=>{if(!store.canUseQuestion(b.dataset.qcheck,'bank'))b.checked=false;add(b.dataset.qcheck);});
 container.querySelectorAll('[data-qaction]').forEach(b=>{b.innerHTML=`${state.selected.has(b.dataset.qaction)?'담기 취소':'문항 담기'} ${icon('plus')}`;b.onclick=()=>add(b.dataset.qaction);});
 container.querySelectorAll('[data-qopen]').forEach(b=>b.onclick=()=>requestQuestion(b.dataset.qopen,'bank'));
 container.querySelectorAll('[data-remove-question]').forEach(b=>b.onclick=()=>{state.selected.delete(b.dataset.removeQuestion);rerender();});
 container.querySelector('[data-clear-basket]').onclick=()=>{state.selected.clear();rerender();};
 container.querySelector('[data-basket-paper]').onclick=()=>{const ids=chosen.map(q=>q.id);if(!ids.length)return;if(ids.some(id=>!store.canUseQuestion(id,'bank')))return subscribe('bank');openPaperDestination(ctx,ids,'bank',{originLabel:'문제은행 · '+state.grade,filters:{source:'bank',grade:state.grade}});};
 container.querySelector('[data-studio-help]').onclick=()=>toast('학년과 단원을 고른 뒤 문항을 체크하세요. 담은 문항에서 내 문제지에 추가할 수 있어요.');
}
